Replace DeletePendings (lines 559-568) with the version below. The normal path still uses CTrade. While stopping, it sends a raw asynchronous remove request: OrderSendAsync does not wait, which fits the ~2.5 s deinit budget. This compiles in the g++/clang++ harness and is pure ASCII (copy at lab/audit/scratch/mql5_v21/compile_api/fix_DeletePendings.mq5.txt):

void DeletePendings()
  {
   for(int i = OrdersTotal() - 1; i >= 0; i--)
     {
      ulong t = OrderGetTicket(i);
      if(t == 0) continue;
      if(OrderGetString(ORDER_SYMBOL) != _Symbol || OrderGetInteger(ORDER_MAGIC) != InpMagic) continue;
      if(!IsStopped()) { g_trade.OrderDelete(t); continue; }
      // OnDeinit (EA retire) : _StopFlag est leve, CTrade refuse tout (CTrade::IsStopped, 10027) -> requete directe
      MqlTradeRequest rq;
      MqlTradeResult  rs;
      ZeroMemory(rq);
      ZeroMemory(rs);
      rq.action = TRADE_ACTION_REMOVE;
      rq.order  = t;
      if(!OrderSendAsync(rq, rs))
         Alert("GoldOrb : ordre #", t, " NON supprime (", rs.retcode, "), supprimez-le vous-meme.");
     }
  }

